private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    if (suffixLen > str.length()) {
        return false;
    }
    if (ignoreCase) {
        String tail = str.substring(str.length() - suffixLen);
        return tail.equalsIgnoreCase(suffix);
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null && suffix == null) return true;
    if (str == null || suffix == null) return false;
    int sLen = suffix.length();
    int rLen = str.length();
    if (sLen > rLen) return false;
    return str.regionMatches(ignoreCase, rLen - sLen, suffix, 0, sLen);
}

