private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; ++i) {
        int entry   = currentFrame[i];
        int tag     = entry >>> 24;
        int payload = entry & 0xFFFFFF;
        stackMapTableEntries.putByte(tag);
        switch (tag) {
            case 7:  // OBJECT
                stackMapTableEntries.putShort(payload);
                break;
            case 8:  // UNINIT
                stackMapTableEntries.putShort(payload);
                break;
            default: // CATEGORY_1 or simple categories
                stackMapTableEntries.putByte((byte) payload);
                break;
        }
    }
}

