public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Split the vertices into two partitions based on key convention.
    // Keys that start with "A" or "L" belong to the left partition,
    // all others belong to the right partition.
    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();
    for (java.util.Map.Entry<String,V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        if (key != null && !key.isEmpty() && (key.charAt(0) == 'A' || key.charAt(0) == 'L')) {
            left.add(entry.getValue());
        } else {
            right.add(entry.getValue());
        }
    }
    // Add edges between every vertex in the left partition and every vertex in the right partition
    for (V u : left) {
        for (V v : right) {
            try {
                target.addEdge(u, v);
            } catch (Exception e) {
                // ignore if the edge already exists or cannot be added
            }
        }
    }
}

