protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), new ArrayList<>(), 0.0);
    }
    // Map each vertex to the list of outgoing edges that belong to the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    // Copy of remaining edges to be processed
    Set<E> remaining = new LinkedHashSet<>(tour);
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
    }
    // Start from an arbitrary edge
    E firstEdge = remaining.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;
    List<V> vertexList = new ArrayList<>();
    vertexList.add(start);
    List<E> edgeList = new ArrayList<>();
    double weight = 0.0;
    // Traverse edges to build a path
    while (!remaining.isEmpty()){
        List<E> edgesFromCur = adjacency.get(current);
        if (edgesFromCur == null) break;
        E chosen = null;
        for (E cand : edgesFromCur){
            if (remaining.contains(cand)){
                chosen = cand;
                break;
            }
        }
        if (chosen == null) break;
        remaining.remove(chosen);
        edgeList.add(chosen);
        weight += graph.getEdgeWeight(chosen);
        V next = graph.getEdgeTarget(chosen);
        vertexList.add(next);
        current = next;
    }
    V end = vertexList.isEmpty() ? null : vertexList.get(vertexList.size() - 1);
    return new GraphWalk<>(graph, start, end, vertexList, edgeList, weight);
}

