            if (remaining.contains(cand)){
                chosen = cand;
                break;
            }
        }
        if (chosen == null) break;
        remaining.remove(chosen);
        edgeList.add(chosen);
        weight += graph.getEdgeWeight(chosen);
        V next = graph.getEdgeTarget(chosen);
        vertexList.add(next);
        current = next;
    }
    V end = vertexList.isEmpty() ? null : vertexList.get(vertexList.size() - 1);
    return new GraphWalk<>(graph, start, end, vertexList, edgeList, weight);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    // Create a mutable copy of the edge set to work with.
    Set<E> remaining = new HashSet<>(tour);
    // Pick an arbitrary starting edge.
    Iterator<E> it = remaining.iterator();
    E startEdge = it.next();
    it.remove();
    // Determine the starting vertex and the current vertex.
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);
    // Maintain the ordering of edges for the tour.
    List<E> orderedEdges = new ArrayList<>();
    orderedEdges.add(startEdge);
    // Continue walking the tour until all edges are used.
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> remIter = remaining.iterator();
        while (remIter.hasNext()) {
            E e = remIter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)) {
                orderedEdges.add(e);
                currentVertex = tgt;
                remIter.remove();
                found = true;
                break;
            } else if (tgt.equals(currentVertex)) {
                orderedEdges.add(e);
                currentVertex = src;
                remIter.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Provided edge set does not form a connected tour");
        }
    }
    // The tour is closed: currentVertex should equal startVertex.
    if (!currentVertex.equals(startVertex)) {
        // Optionally add the edge that returns to the start if missing.
        // For a proper tour this shouldn't happen.
    }
    // Construct and return a GraphPath representing the tour.
    return new DefaultGraphPath<>(graph, startVertex, startVertex, orderedEdges);
