protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // Convert the set of edges into a list to preserve a traversal order
    List<E> edges = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();
    // If there is at least one edge, pick one vertex to start the path
    if (!edges.isEmpty()){
        // Assume edges are directed and use the out‑vertex of the first edge
        vertices.add(edges.get(0).getOutVertex());
    }
    // Construct a GraphPath using the visited vertices and the traversed edges
    // The constructor signature is: GraphPath(List<V> visited, List<E> traversed, Graph<V,E> g)
    return new GraphPath<>(vertices, edges, graph);
}

