protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) return null;
    // Map each source vertex to the outgoing edge in the tour
    Map<V, E> next = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        next.put(src, e);
    }
    // Determine the set of target vertices to find a start vertex
    Set<V> targets = new HashSet<>();
    for (E e : tour) {
        targets.add(graph.getEdgeTarget(e));
    }
    V start = null;
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        if (!targets.contains(src)) { // src is not a target elsewhere
            start = src;
            break;
        }
    }
    if (start == null) start = graph.getEdgeSource(tour.iterator().next()); // fallback
    // Walk through the tour, assembling edges in order
    List<E> ordered = new ArrayList<>();
    V cur = start;
    while (ordered.size() < tour.size()) {
        E e = next.get(cur);
        if (e == null) break;
        ordered.add(e);
        cur = graph.getEdgeTarget(e);
    }
    return new GraphPath<>(graph, ordered);
}

