    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) suffix.add(0);
    long sum = 0L;
    int acc = 0;
    for (int i = n - 1; i >= 0; i--) {
        int v = bounds.get(i);
        acc += v;
        suffix.set(i, acc);
        sum += v;
    }
    return new Pair<>(suffix, sum);
}

