@Override public Action inspect(AtmosphereResource r){
    // Automatically suspend the resource for all transports except WebSocket
    if (r.getTransport() != AtmosphereResource.TRANSPORT.WEBSOCKET) {
        try {
            // Only suspend if not already suspended
            if (!r.isSuspended()) {
                r.suspend();
            }
        } catch (Exception e) {
            // ignore exceptions during suspend to avoid impacting the workflow
        }
    }
    return Action.CONTINUE;
}

