String function ( String path , String relativePath ) {
    // Determine if the original path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Determine the directory part of the original path
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        if (lastSlash >= 0) {
            baseDir = path.substring(0, lastSlash + 1); // include slash
        } else {
            baseDir = ""; // no directory component
        }
    }
    // Combine base directory with the relative path
    String combined = baseDir + relativePath;
    // Split the combined path into components
    String[] parts = combined.split("/", -1); // keep trailing empty parts
    // Normalize the components using a stack
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            // skip
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            } else if (!isAbsolute) {
                // relative path attempts to go above current directory
                stack.push("..");
            }
        } else {
            stack.push(part);
        }
    }
    // Build the result from the stack (reverse order)
    java.util.List<String> rev = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        rev.add(stack.pop());
    }
    java.lang.String joined = String.join("/", rev);
    if (isAbsolute) {
        return "/" + joined;
    } else {
        return joined.isEmpty() ? "." : joined;
    }
}

