void function ( int nameStart , StringBuffer buf ) { 
    String fullName = name; 
    if (fullName == null || nameStart < 0 || nameStart >= fullName.length()) { 
        return; 
    } 
    StringBuilder abbrev = new StringBuilder(); 
    boolean startWord = true; 
    int len = fullName.length(); 
    for (int i = nameStart; i < len; i++) { 
        char c = fullName.charAt(i); 
        if (Character.isWhitespace(c)) { 
            startWord = true; 
        } else { 
            if (startWord) { 
                abbrev.append(Character.toUpperCase(c)).append('.'); 
                startWord = false; 
            } 
        } 
    } 
    buf.append(abbrev.toString()); 
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Guard against null or empty name
    if (name == null || name.length() == 0) {
        return;
    }
    // Ensure the start index is within bounds
    int start = nameStart < 0 ? 0 : (nameStart >= name.length() ? name.length() : nameStart);
    // We'll create an abbreviation of up to 3 characters
    int count = 0;
    for (int i = start; i < name.length() && count < 3; i++) {
        char c = name.charAt(i);
        // Stop on whitespace or null character (if present)
        if (Character.isWhitespace(c) || c == 0) {
            break;
        }
        buf.append(c);
        count++;
    }
}

