public Mappings diffStructure(String tableName, Mappings mappings) {
    // Obtain the current mapping from the index (history mapping)
    Mappings currentMapping = getMapping(tableName);
    // Extract property maps from input and current mappings
    Map<String, Object> inputProps = mappings.getProperties();
    Map<String, Object> currentProps = currentMapping.getProperties();
    // Create a map to hold differences
    Map<String, Object> diffProps = new HashMap<>();
    // Iterate over current properties; if a field is not present in input and is not _source, add to diff
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if (!"_source".equals(field) && !inputProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }
    // Return a new Mappings instance containing only the differing fields
    return new Mappings(diffProps);
}

